export const KEY='math-practice-v1';
export function readHistory(storage){try{let a=JSON.parse(storage.getItem(KEY)||'[]');return Array.isArray(a)?a.filter(r=>r&&typeof r.skill==='string'&&typeof r.correct==='boolean'&&Number.isFinite(r.time)&&Number.isFinite(r.hints)):[]}catch{return []}}
export function stats(rows){let streak=0,best=0;for(const r of rows){streak=r.correct?streak+1:0;best=Math.max(best,streak)}let recent=rows.slice(-12),weight=recent.reduce((s,r,i)=>s+(r.correct?i+1:0),0)/(recent.length*(recent.length+1)/2||1);return {attempted:rows.length,correct:rows.filter(r=>r.correct).length,accuracy:rows.length?Math.round(100*rows.filter(r=>r.correct).length/rows.length):0,streak,best,hints:rows.reduce((s,r)=>s+r.hints,0),mastery:recent.length<3?'Learning':weight>=.9&&recent.length>=8?'Mastered':weight>=.75?'Proficient':weight>=.5?'Developing':'Learning'}}
export function adaptive(rows,level){const last=rows.slice(-4);if(last.length===4&&last.every(r=>r.correct&&!r.hints))return Math.min(2,level+1);const three=rows.slice(-3);if(three.length>=3&&three.filter(r=>!r.correct).length>=2)return Math.max(0,level-1);return level}
